def comps4(g, bg):
    lab=np.full(g.shape,-1); out=[]
    for r in range(g.shape[0]):
        for c in range(g.shape[1]):
            if g[r,c]!=bg and lab[r,c]==-1:
                stack=[(r,c)]; lab[r,c]=len(out); cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        yy,xx=y+dy,x+dx
                        if 0<=yy<g.shape[0] and 0<=xx<g.shape[1] and g[yy,xx]!=bg and lab[yy,xx]==-1:
                            lab[yy,xx]=len(out); stack.append((yy,xx))
                out.append((g[r,c],cells))
    return out

